package proofimage

import (
	"context"
	"errors"
	"os"
	"os/exec"
	"testing"

	app "github.com/AY2627S1-CS3219-P1/FoC/order-service/internal/order"
)

// Actual decoding and the supported formats come from user decision Q2 and
// NFR-18. Fixtures were generated by ImageMagick, independently of Decoder.
func TestSupportedProofImagesDecode(t *testing.T) {
	if _, err := exec.LookPath("magick"); err != nil {
		t.Skip("ImageMagick with libheif is required for actual image decoding")
	}
	for _, tc := range []struct{ media, file string }{
		{"image/jpeg", "valid.jpeg"},
		{"image/png", "valid.png"},
		{"image/webp", "valid.webp"},
		{"image/heic", "valid.heic"},
		{"image/heif", "valid.heic"},
	} {
		t.Run(tc.media, func(t *testing.T) {
			body, err := os.ReadFile("testdata/" + tc.file)
			if err != nil {
				t.Fatal(err)
			}
			if err := (NewDecoder("")).Validate(t.Context(), tc.media, body); err != nil {
				t.Fatal(err)
			}
			if err := (NewDecoder("")).Validate(t.Context(), tc.media, []byte("not an image")); !errors.Is(err, app.ErrPrecondition) {
				t.Fatalf("accepted disguised text: %v", err)
			}
		})
	}
}

func TestProofDecoderRejectsTruncatedAndMismatchedImages(t *testing.T) {
	if _, err := exec.LookPath("magick"); err != nil {
		t.Skip("ImageMagick is required")
	}
	body, err := os.ReadFile("testdata/valid.png")
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name, media string
		body        []byte
	}{
		{"truncated", "image/png", body[:len(body)/2]},
		{"wrong format", "image/jpeg", body},
		{"unsupported", "image/svg+xml", []byte("<svg/>")},
		{"oversized", "image/png", make([]byte, 10000001)},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if err := (NewDecoder("")).Validate(t.Context(), tc.media, tc.body); !errors.Is(err, app.ErrPrecondition) {
				t.Fatalf("got %v", err)
			}
		})
	}
}

func TestProofDecoderMissingRuntimeIsNotAnUploadOutage(t *testing.T) {
	if err := (NewDecoder("/not/an/installed/decoder")).Validate(context.Background(), "image/png", []byte("body")); !errors.Is(err, app.ErrUnavailable) {
		t.Fatal(err)
	}
}

// The supported byte contract includes ordinary compressed phone photographs;
// cache limits must not make the documented 24MP validation budget unusable.
func TestProofDecoderAcceptsOrdinaryHighResolutionPhotos(t *testing.T) {
	binary, err := exec.LookPath("magick")
	if err != nil {
		t.Skip("ImageMagick is required")
	}
	for _, dimensions := range []string{"5472x3648", "6000x4000"} {
		t.Run(dimensions, func(t *testing.T) {
			body, err := exec.CommandContext(t.Context(), binary, "-size", dimensions, "xc:white", "jpeg:-").Output()
			if err != nil {
				t.Fatal(err)
			}
			if len(body) > 10000000 {
				t.Fatal("fixture exceeds byte contract")
			}
			if err := NewDecoder(binary).Validate(t.Context(), "image/jpeg", body); err != nil {
				t.Fatal(err)
			}
		})
	}
}

// A server execution deadline is an unknown validation result, not evidence
// that the submitted photograph is invalid.
func TestProofDecoderExecutionTimeoutIsRetryable(t *testing.T) {
	binary := t.TempDir() + "/slow-decoder"
	if err := os.WriteFile(binary, []byte("#!/bin/sh\nexec sleep 7\n"), 0700); err != nil {
		t.Fatal(err)
	}
	if err := NewDecoder(binary).Validate(t.Context(), "image/jpeg", []byte("body")); !errors.Is(err, app.ErrUnavailable) {
		t.Fatalf("timeout classified as invalid media: %v", err)
	}
}

// A killed native decoder must preserve an admitted receipt for retry rather
// than label previously verified immutable evidence as invalid media.
func TestProofDecoderExternalKillIsRetryable(t *testing.T) {
	binary := t.TempDir() + "/killed-decoder"
	if err := os.WriteFile(binary, []byte("#!/bin/sh\nkill -KILL $$\n"), 0700); err != nil {
		t.Fatal(err)
	}
	if err := NewDecoder(binary).Validate(t.Context(), "image/png", []byte("previously verified pixels")); !errors.Is(err, app.ErrUnavailable) {
		t.Fatalf("external kill classified as invalid media: %v", err)
	}
}

// A decoder that exceeds the bounded RGB output has a known invalid result,
// even when os/exec reports its writer error instead of a process exit error.
func TestProofDecoderOutputLimitRejectsMedia(t *testing.T) {
	binary := t.TempDir() + "/verbose-decoder"
	if err := os.WriteFile(binary, []byte("#!/bin/sh\nexec dd if=/dev/zero bs=1539 count=1 2>/dev/null\n"), 0700); err != nil {
		t.Fatal(err)
	}
	if err := NewDecoder(binary).Validate(t.Context(), "image/png", []byte("pixels")); !errors.Is(err, app.ErrPrecondition) {
		t.Fatalf("output limit classified as retryable: %v", err)
	}
}
